window.AUTH=window.AUTH||{};window.AUTH["21-234"]={"d":"21-234","id":"2021/21-234","n":"George v. McDonough","briefs":[{"k":"petitioner","label":"Brief of petitioner Kevin R. George","date":"2022-02-28","url":"https://www.supremecourt.gov/DocketPDF/21/21-234/215137/20220228135615694_George%20Merits%20Opening%20Brief.pdf","side":"pet","n":144},{"k":"respondent","label":"Brief of respondent Denis R. McDonough, Secretary of Veterans Affairs","date":"2022-03-30","url":"https://www.supremecourt.gov/DocketPDF/21/21-234/220030/20220401123445305_21-234bsUnitedStates%20CORRECTED%20COPY.pdf","side":"res","n":101},{"k":"reply","label":"Reply of petitioner Kevin R. George","date":"2022-04-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-234/220571/20220408105422250_George%20Merits%20Reply%20Brief.pdf","side":"pet","n":56}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r47_m6hn.pdf","tr":true,"items":[{"t":"case","label":"Allin v. Brown","cite":"6 Vet. App. 207","y":1994,"url":"https://www.courtlistener.com/c/Vet.%20App./6/207/","by":{"0":"40"}},{"t":"case","label":"Anderson v. Pac. Coast S.S. Co.","cite":"225 U.S. 187","y":1912,"id":"scdb/1911-064","sc":1,"sum":"When the Federal Constitution was adopted each State had its own pilotage regulations.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Banks v. Chicago Grain Trimmers Ass’n","cite":"390 U.S. 459","y":1968,"id":"1967/59","sc":1,"sum":"Petitioner filed a claim against her late husband's employer for compensation death benefits under the Longshoremen's and Harbor Workers' Compensation Act, alleging that his fall at home on January 30, 1961, from which he later died, resulted from a work-connected injury sustained on January 26. A Department of Labor Deputy Commissioner rejected the claim for failure to establish a work-connected injury. Thereafter, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Berger v. Brown","cite":"10 Vet. App. 166","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/166/","op":2,"ar":4,"by":{"0":"26, 40","1":"37","2":"8, 9"}},{"t":"case","label":"Bobby v. Bies","cite":"556 U.S. 825","y":2009,"id":"2008/08-598","sc":1,"sum":"The Court found that the Double Jeopardy Clause did not prevent relitigation of a mental retardation claim because the defendant was never acquitted at trial.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"sum":"Section 201 of the Soldiers' and Sailors' Civil Relief Act of 1940, providing for stays in court proceedings involving persons in military service, addresses to the discretion of the court the question whether \"the ability of... the defendant to conduct his defense is not materially affected by reason of his military service.\" In the circumstances of this case, denial of a stay at the instance of a defendant in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"ar":3,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"0":"31, 41","2":"12, 14, 20"}},{"t":"case","label":"Buck v. Davis","cite":"137 S. Ct. 759","y":2017,"id":"2016/15-8049","sc":1,"sum":"The Court held that the U.S. Court of Appeals for the Fifth Circuit applied an unduly burdensome standard of review on a Certificate of Appealability (COA) for a claim of ineffective assistance of counsel when it denied the COA for failing to demonstrate extraordinary circumstances.","sumSrc":"Oyez","by":{"0":"45, 48","2":"19"}},{"t":"case","label":"Chevron U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"ar":6,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"23, 34, 35","1":"31","2":"3"}},{"t":"case","label":"Christianson v. Colt Indus. Operating Corp.","cite":"486 U.S. 800","y":1988,"id":"1987/87-499","sc":1,"ar":1,"sum":"The principal statutes involved in this case, which arises from a jurisdictional dispute between Courts of Appeals, are 28 U. S. C. § 1295(a)(1)granting the Federal Circuit exclusive jurisdiction over an appeal from a final decision of a federal district court \"if the jurisdiction of that court was based, in whole or in part, on\" 28 U. S. C. § 1338-and § 1338(a), which grants the district courts original …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"30","2":"4"}},{"t":"case","label":"Cotant v. Principi","cite":"17 Vet. App. 116","y":2003,"url":"https://www.courtlistener.com/c/Vet.%20App./17/116/","sum":"Explaining why such a reading could produce “absurd” disparities between veterans whose preexisting conditions were noted at entry and those whose preexisting conditions were not.","sumSrc":"brief:1","by":{"0":"13","1":"28"}},{"t":"case","label":"Coulter v. Weinberger","cite":"527 F.2d 224","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/527/224/","by":{"0":"29"}},{"t":"case","label":"Cousin v. Wilkie","cite":"905 F.3d 1316","y":2018,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/905/1316/","by":{"0":"49"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"23, 35"}},{"t":"case","label":"Damrel v. Brown","cite":"6 Vet. App. 242","y":1994,"url":"https://www.courtlistener.com/c/Vet.%20App./6/242/","op":2,"by":{"0":"40","1":"37, 38","2":"9"}},{"t":"case","label":"Davis v. United States","cite":"564 U.S. 229","y":2011,"id":"2010/09-11328","sc":1,"sum":"The Court held that the good-faith exception to the exclusionary rule applies to a search that was authorized by precedent at the time of the search, but was subsequently ruled unconstitutional.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Dixon v. United States","cite":"381 U.S. 68","y":1965,"id":"1964/486","sc":1,"op":3,"ar":1,"sum":"A partnership to which petitioners belong, in 1952 bought short-term noninterest-bearing notes at discounts. The purchases were assertedly made in reliance on the published acquiescence of the Commissioner of Internal Revenue in Caulkins v. Commissioner. I T. C. 656, aff'd 144 F. 2d 482, where the Tax Court had allowed capital gains treatment of the full amount a taxpayer had received on an \"Accumulative Installment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 35, 42","2":"10"}},{"t":"case","label":"Edgar v. MITE Corp.","cite":"457 U.S. 624","y":1982,"id":"1981/80-1188","sc":1,"sum":"With regard to the Commerce Clause. The Illinois Act imposes burdens on interstate commerce that are excessive in light of the local interests the Act purports to further. Among the ways a corporation can be covered by the Act is if 10% of the class of equity securities subject to the offer is owned by shareholders located in Illinois.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Entergy Corp. v. Riverkeeper, Inc.","cite":"556 U.S. 208","y":2009,"id":"2008/07-588","sc":1,"sum":"The Court found that the Environmental Protection Agency (EPA) was permitted to use a cost-benefit analysis while setting national performance standards for cooling water intake structures.","sumSrc":"Oyez","by":{"0":"24","2":"4"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Fiore v. White","cite":"531 U.S. 225","y":2001,"id":"1999/98-942","sc":1,"sum":"After certifying an question of state law to the Pennsylvania Supreme Court, the U.S. Supreme Court held that Fiore's conviction was not covered by the statute at issue and thus violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Fishgold v. Sullivan Drydock & Repair Corp.","cite":"328 U.S. 275","y":1946,"id":"scdb/1945-102","sc":1,"sum":"After serving in the Army and receiving an honorable discharge, petitioner was reinstated in his former position pursuant to § 8 (a) of the Selective Training and Service Act of 1940. Subsequently, when there was not enough work to keep all employees busy, he was laid off temporarily on nine days while non-veterans with higher shop seniorities were permitted to work; but he was given work when enough became …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Fox v. Bowen","cite":"835 F.2d 1159","y":1987,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/1159/","by":{"0":"28, 40","1":"42"}},{"t":"case","label":"Fugo v. Brown","cite":"6 Vet. App. 40","y":1993,"url":"https://www.courtlistener.com/c/Vet.%20App./6/40/","op":1,"ar":2,"by":{"0":"21, 47","1":"35, 36"}},{"t":"case","label":"Goldstein v. McDonald","cite":"2016 WL 1458490","y":2016,"court":"Vet. App. Apr. 14","by":{"0":"51","2":"21"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":2,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"0":"45, 48","2":"19"}},{"t":"case","label":"Green v. Brown","cite":"10 Vet. App. 111","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/111/","by":{"0":"39"}},{"t":"case","label":"Groves v. Peake","cite":"524 F.3d 1306","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/524/1306/","sum":"Finding CUE as a matter of law after noting Veterans Court’s “legal error”.","sumSrc":"brief:0","by":{"0":"49"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Harper v. Virginia Dep’t of Tax’n","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"op":2,"sum":"In Davis v. Michigan Dept. of Treasury,489 U. S. 803, this Court invalidated Michigan's practice of taxing retirement benefits paid by the Federal Government while exempting retirement benefits paid by the State or its political subdivisions. Because Michigan conceded that a refund to federal retirees was the appropriate remedy, the Court remanded for entry of judgment against the State. Virginia subsequently …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"16"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":2,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"4, 31, 32","1":"5, 10, 25"}},{"t":"case","label":"Herron v. Shulkin","cite":"2017 WL 3224526","y":2017,"court":"Vet. App. July 31","by":{"0":"51"}},{"t":"case","label":"I.N.S. v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"21, 29"}},{"t":"case","label":"James B. Beam Distilling Co. v. Georgia","cite":"501 U.S. 529","y":1991,"id":"1990/89-680","sc":1,"sum":"The judgment is reversed, and the case is remanded. 259 Ga. 363, 382 S. E. 2d 95, reversed and remanded. JUSTICE SOUTER, joined by JUSTICE STEVENS, concluded that once this Court has applied a rule of law to the litigants in one case, it must do so with respect to all others not barred by procedural requirements or res judicata.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Kennedy v. Lubar","cite":"273 F.3d 1293","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/273/1293/","by":{"0":"30"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"32","2":"5, 15"}},{"t":"case","label":"Ko v. Brown","cite":"1993 WL 426404","y":1993,"court":"Vet. App. Sept. 24","by":{"0":"27","2":"8"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"op":2,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"34","1":"39","2":"14"}},{"t":"case","label":"La. Pub. Serv. Comm’n v. F.C.C.","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Look v. Derwinski","cite":"2 Vet. App. 157","y":1992,"url":"https://www.courtlistener.com/c/Vet.%20App./2/157/","op":3,"ar":9,"by":{"0":"26, 27, 41","1":"38","2":"9"}},{"t":"case","label":"Manhattan Gen. Equip. Co. v. Comm’r","cite":"297 U.S. 129","y":1936,"id":"scdb/1935-080","sc":1,"ar":1,"sum":"1. A loss resulting from the sale in 1926 of securities in respect of which a distribution pursuant to a plan of reorganization had been made, held properly determined, for the purpose of computing income tax under the Revenue Act of 1926, by the method prescribed by Art. 1599 of Treasury Regulations 65, as amended April 3, 1928, rather than by the original regulation promulgated August 28, 1926, where the effect of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","2":"4"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"sum":"The Court held that parts of eastern Oklahoma are an Indian reservation subject to exclusive federal jurisdiction for certain crimes under the Indian Major Crimes Act.","sumSrc":"Oyez","by":{"0":"47, 48"}},{"t":"case","label":"Mines v. Sullivan","cite":"981 F.2d 1068","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/1068/","by":{"0":"28"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Monell v. Dep’t of Soc. Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"ar":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"36","1":"32","2":"16"}},{"t":"case","label":"Monk v. Shulkin","cite":"855 F.3d 1312","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/855/1312/","by":{"0":"44"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"ar":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"36","1":"32","2":"16"}},{"t":"case","label":"Munsinger v. Schweiker","cite":"709 F.2d 1212","y":1983,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/709/1212/","by":{"0":"28","1":"42"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"30","1":"32"}},{"t":"case","label":"Nat’l Labor Relations Bd. v. Alt. Ent., Inc.","cite":"858 F.3d 393","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/393/","by":{"0":"32"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"op":3,"ar":2,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 36","1":"32","2":"15, 16"}},{"t":"case","label":"Roberts v. U.S. ex rel. Valentine","cite":"176 U.S. 221","y":1900,"id":"scdb/1899-118","sc":1,"sum":"A judgment of the Court of Claims, under tbe act of June 16, 1880, c. 243, in favor of tlie claimant, against tbe District of Columbia,‘upon a certificate of. the board of audit of the District, in an action.commenced'in 1880, is not affected by the provision in the act of July 6, 1884, c. 227, forbidding the payment of such certificates, not presented for. payment ‘ within one year from the date of the passage of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Robertson v. Seattle Audubon Soc.","cite":"503 U.S. 429","y":1992,"id":"1991/90-1596","sc":1,"sum":"The Supreme Court held that §318 did not violate Article III because it made changes to the law by replacing the legal standards of the five challenged statutes. It did not make any findings of law or fact, or compel any results in the pending cases. The explicit reference to the cases only served to identify the statutes underlying those cases.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Russell v. Principi","cite":"3 Vet. App. 310","y":1992,"url":"https://www.courtlistener.com/c/Vet.%20App./3/310/","op":2,"ar":10,"by":{"0":"9, 21, 24, 40, 47","1":"12, 13, 14, 36","2":"2, 3, 4"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"sum":"The Court held that an individual has standing to maintain a suit when he acquires a \"judicially cognizable\" interest in ensuring compliance with a previous judgment in his favor. The Court also held that a court may not order an injunction in a case when it fails to consider all the circumstances bearing on the need for preventive relief.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"24","1":"27"}},{"t":"case","label":"Smith v. Brown","cite":"35 F.3d 1516","y":1994,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/35/1516/","by":{"0":"8","1":"26"}},{"t":"case","label":"Sulik v. Taney County","cite":"393 F.3d 765","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/393/765/","by":{"0":"30"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Grp. Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"ar":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Traynor v. Turnage","cite":"485 U.S. 535","y":1988,"id":"1987/86-622","sc":1,"sum":"Petitioners in these cases are honorably discharged veterans who did not exhaust their \"GI Bill\" educational assistance benefits within 10 years following their military service, as required by 38 U. S. C. § 1662(a)(1). Under that section, veterans may obtain an extension of the delimiting period if they were prevented from using their benefits earlier by \"a physical or mental disorder which was not the result of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"25"}},{"t":"case","label":"Unicolors, Inc. v. H&M Hennes & Mauritz, L.P.","cite":"595 U.S. __","y":2022,"id":"2021/20-915","sc":1,"sum":"Lack of either factual or legal knowledge can excuse an inaccuracy in a copyright registration under 17 U. S. C. §411(b)(1)(A)’s safe harbor.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22"}},{"t":"case","label":"United States v. Estate of Donnelly","cite":"397 U.S. 286","y":1970,"id":"1969/104","sc":1,"sum":"The Government's tax lien was properly filed in-the District Court and was thus entitled to priority. Any reliance that the Carlsons may have placed on the lower courts' construction of § 3672 which the Government had never accepted and which this Court rejected in United States v. Union Central Life Ins. Co.,","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"sum":"The Court ruled that there is an exception to the exclusionary rule for evidence gathered in \"good faith.\"","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"United States v. Oregon","cite":"366 U.S. 643","y":1961,"id":"1960/329","sc":1,"sum":"The United States was entitled 'to the property as such trustee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"op":1,"sum":"The Court held that Chapter 13 bankruptcy plans which discharge student loans are not void if the debtor fails to provide evidence of \"undue hardship\" in an adversary proceeding.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Utah Power & Light Co. v. United States","cite":"243 U.S. 389","y":1917,"id":"scdb/1916-144","sc":1,"sum":"The power to regulate the use of the lands of the United States, and to prescribe the conditions upon which rights in them may be acquired by others,' is vested exclusively in Congress.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24, 42"}},{"t":"case","label":"Vanerson v. West","cite":"12 Vet. App. 254","y":1999,"url":"https://www.courtlistener.com/c/Vet.%20App./12/254/","by":{"0":"50","2":"21"}},{"t":"case","label":"Wagner v. Principi","cite":"370 F.3d 1089","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/370/1089/","op":9,"ar":5,"sum":"Explaining why such a reading could produce “absurd” disparities between veterans whose preexisting conditions were noted at entry and those whose preexisting conditions were not.","sumSrc":"brief:1","by":{"0":"13, 24, 25","1":"10, 27, 28","2":"4, 5, 22"}},{"t":"case","label":"Walters v. Nat’l Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 5, 46","1":"5"}},{"t":"case","label":"Wilbur v. U.S. ex rel. Kadrie","cite":"281 U.S. 206","y":1930,"id":"scdb/1929-037","sc":1,"by":{"0":"29"}},{"t":"case","label":"Willsey v. Peake","cite":"535 F.3d 1368","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/535/1368/","by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"44"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"44","1":"10"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"3"}},{"t":"usc","label":"38 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/38/101","subs":["(13)","(14)","(15)","(16)"],"stext":{"head":"§101. Definitions","paras":[[0,"For the purposes of this title—"],[0,"(1) The terms \"Secretary\" and \"Department\" mean the Secretary of Veterans Affairs and the Department of Veterans Affairs, respectively."],[0,"(2) The term \"veteran\" means a person who served in the active military, naval, air, or space service, and who was discharged or released therefrom under conditions other than dishonorable."],[0,"(3) The term \"surviving spouse\" means (except for purposes of chapter 19 of this title) a person who was the spouse of a veteran at the time of the veteran's death, and who lived with the veteran continuously from the date of marriage to the date of the veteran's death (except where there was a separation which was due to the misconduct of, or procured by, the veteran without the fault of the spouse) and who has not remarried."],[0,"(4)(A) The term \"child\" means (except for purposes of chapter 19 of this title (other than with respect to a child who is an insurable dependent under subparagraph (B) or (C) of section 1965(10) of such chapter) and section 8502(b) of this title) a person who is unmarried and—"],[1,"(i) who is under the age of eighteen years;"],[1,"(ii) who, before attaining the age of eighteen years, became permanently incapable of self-support; or"],[1,"(iii) who, after attaining the age of eighteen years and until completion of education or training (but not after attaining the age of twenty-three years), is pursuing a course of instruction at an approved educational institution;"],[0,"and who is a legitimate child, a legally adopted child, a stepchild who is a member of a veteran's household or was a member at the time of the veteran's death, or an illegitimate child but, as to the alleged father, only if acknowledged in writing signed by him, or if he has been judicially ordered to contribute to the child's support or has been, before his death, judicially decreed to be the father of such child, or if he is otherwise shown by evidence satisfactory to the Secretary to be the father of such child. A person shall be deemed, as of the date of death of a veteran, to be the legally adopted child of such veteran if such person was at the time of the veteran's death living in the veteran's household and was legally adopted by the veteran's surviving spouse before August 26, 1961, or within two years after the veteran's death; however, this sentence shall not apply if at the time of the veteran's death, such person was receiving regular contributions toward the person's support from some individual other than the veteran or the veteran's spouse, or from any public or private welfare organization which furnishes services or assistance for children. A person with respect to whom an interlocutory decree of adoption has been issued by an appropriate adoption authority shall be recognized thereafter as a legally adopted child, unless and until that decree is rescinded, if the child remains in the custody of the adopting parent or parents during the interlocutory period. A person who has been placed for adoption under an agreement entered into by the adopting parent or parents with any agency authorized under law to so act shall be recognized thereafter as a legally adopted child, unless and until such agreement is terminated, if the child remains in the custody of the adopting parent or parents during the period of placement for adoption under such agreement. A person described in clause (ii) of the first sentence of this subparagraph who was a member of a veteran's household at the time the person became 18 years of age and who is adopted by the veteran shall be recognized as a legally adopted child of the veteran regardless of the age of such person at the time of adoption."],[0,"(B) For the purposes of subparagraph (A) of this paragraph, in the case of an adoption under the laws of any jurisdiction other than a State (as defined in section 101(20) of this title and including the Commonwealth of the Northern Mariana Islands)—"],[1,"(i) a person residing outside any of the States shall not be considered to be a legally adopted child of a veteran during the lifetime of such veteran (including for purposes of this subparagraph a Commonwealth Army veteran or new Philippine Scout, as defined in section 3566 of this title) unless such person—"],[2,"(I) was less than eighteen years of age at the time of adoption;"],[2,"(II) is receiving one-half or more of such person's annual support from such veteran;"],[2,"(III) is not in the custody of such person's natural parent, unless such natural parent is such veteran's spouse; and"],[2,"(IV) is residing with such veteran (or in the case of divorce following adoption, with the divorced spouse who is also an adoptive or natural parent) except for periods during which such person is residing apart from such veteran (or such divorced spouse) for purposes of full-time attendance at an educational institution or during which such person or such veteran (or such divorced spouse) is confined in a hospital, nursing home, other health-care facility, or other institution; and"],[1,"(ii) a person shall not be considered to have been a legally adopted child of a veteran as of the date of such veteran's death and thereafter unless—"],[2,"(I) at any time within the one-year period immediately preceding such veteran's death, such veteran was entitled to and was receiving a dependent's allowance or similar monetary benefit under this title for such person; or"],[2,"(II) for a period of at least one year prior to such veteran's death, such person met the requirements of clause (i) of this subparagraph."],[0,"(5) The term \"parent\" means (except for purposes of chapter 19 of this title) a father, a mother, a father through adoption, a mother through adoption, or an individual who for a period of not less than one year stood in the relationship of a parent to a veteran at any time before the veteran's entry into active military, naval, air, or space service or if two persons stood in the relationship of a father or a mother for one year or more, the person who last stood in the relationship of father or mother before the veteran's last entry into active military, naval, air, or space service."],[0,"(6) The term \"Spanish-American War\" (A) means the period beginning on April 21, 1898, and ending on July 4, 1902, (B) includes the Philippine Insurrection and the Boxer Rebellion, and (C) in the case of a veteran who served with the United States military forces engaged in hostilities in the Moro Province, means the period beginning on April 21, 1898, and ending on July 15, 1903."],[0,"(7) The term \"World War I\" (A) means the period beginning on April 6, 1917, and ending on November 11, 1918, and (B) in the case of a veteran who served with the United States military forces in Russia, means the period beginning on April 6, 1917, and ending on April 1, 1920."],[0,"(8) The term \"World War II\" means (except for purposes of chapters 31 and 37 of this title) the period beginning on December 7, 1941, and ending on December 31, 1946."],[0,"(9) The term \"Korean conflict\" means the period beginning on June 27, 1950, and ending on January 31, 1955."],[0,"(10) The term \"Armed Forces\" means the United States Army, Navy, Marine Corps, Air Force, Space Force, and Coast Guard, including the reserve components thereof."],[0,"(11) The term \"period of war\" means the Spanish-American War, the Mexican border period, World War I, World War II, the Korean conflict, the Vietnam era, the Persian Gulf War, and the period beginning on the date of any future declaration of war by the Congress and ending on the date prescribed by Presidential proclamation or concurrent resolution of the Congress."],[0,"(12) The term \"veteran of any war\" means any veteran who served in the active military, naval, air, or space service during a period of war."],[0,"(13) The term \"compensation\" means a monthly payment made by the Secretary to a veteran because of service-connected disability, or to a surviving spouse, child, or parent of a veteran because of the service-connected death of the veteran occurring before January 1, 1957."],[0,"(14) The term \"dependency and indemnity compensation\" means a monthly payment made by the Secretary to a surviving spouse, child, or parent (A) because of a service-connected death occurring after December 31, 1956, or (B) pursuant to the election of a surviving spouse, child, or parent, in the case of such a death occurring before January 1, 1957."],[0,"(15) The term \"pension\" means a monthly or other periodic payment made by the Secretary to a veteran because of service, age, or non-service-connected disability, or to a surviving spouse or child of a veteran because of the non-service-connected death of the veteran."],[0,"(16) The term \"service-connected\" means, with respect to disability or death, that such disability was incurred or aggravated, or that the death resulted from a disability incurred or aggravated, in line of duty in the active military, naval, air, or space service."],[0,"(17) The term \"non-service-connected\" means, with respect to disability or death, that such disability was not incurred or aggravated, or that the death did not result from a disability incurred or aggravated, in line of duty in the active military, naval, air, or space service."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Veterans' Benefits","by":{"0":"4, 4, 4, 11","1":"5"}},{"t":"usc","label":"38 U.S.C. § 223","url":"https://www.law.cornell.edu/uscode/text/38/223","subs":["(c)(1988)"],"by":{"0":"43"}},{"t":"usc","label":"38 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/38/501","subs":["(a)"],"stext":{"head":"§501. Rules and regulations","paras":[[0,"(a) The Secretary has authority to prescribe all rules and regulations which are necessary or appropriate to carry out the laws administered by the Department and are consistent with those laws, including—"],[1,"(1) regulations with respect to the nature and extent of proof and evidence and the method of taking and furnishing them in order to establish the right to benefits under such laws;"],[1,"(2) the forms of application by claimants under such laws;"],[1,"(3) the methods of making investigations and medical examinations; and"],[1,"(4) the manner and form of adjudications and awards."],[0,"(b) Any rule, regulation, guideline, or other published interpretation or order (and any amendment thereto) issued pursuant to the authority granted by this section or any other provision of this title shall contain citations to the particular section or sections of statutory law or other legal authority upon which such issuance is based. The citation to the authority shall appear immediately following each substantive provision of the issuance."],[0,"(c) In applying section 552(a)(1) of title 5 to the Department, the Secretary shall ensure that subparagraphs (C), (D), and (E) of that section are complied with, particularly with respect to opinions and interpretations of the General Counsel."],[0,"(d) The provisions of section 553 of title 5 shall apply, without regard to subsection (a)(2) of that section, to matters relating to loans, grants, or benefits under a law administered by the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/501?type=usc&year=mostrecent&link-type=html"},"head":"§501. Rules and regulations","tname":"Veterans' Benefits","by":{"0":"23","2":"10"}},{"t":"usc","label":"38 U.S.C. § 502","url":"https://www.law.cornell.edu/uscode/text/38/502","stext":{"head":"§502. Judicial review of rules and regulations","paras":[[0,"An action of the Secretary to which section 552(a)(1) or 553 of title 5 (or both) refers is subject to judicial review. Such review shall be in accordance with chapter 7 of title 5 and may be sought only in the United States Court of Appeals for the Federal Circuit. However, if such review is sought in connection with an appeal brought under the provisions of chapter 72 of this title, the provisions of that chapter shall apply rather than the provisions of chapter 7 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/502?type=usc&year=mostrecent&link-type=html"},"head":"§502. Judicial review of rules and regulations","tname":"Veterans' Benefits","by":{"0":"43","1":"23","2":"11, 12"}},{"t":"usc","label":"38 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/38/1110","stext":{"head":"§1110. Basic entitlement","paras":[[0,"For disability resulting from personal injury suffered or disease contracted in line of duty, or for aggravation of a preexisting injury suffered or disease contracted in line of duty, in the active military, naval, air, or space service, during a period of war, the United States will pay to any veteran thus disabled and who was discharged or released under conditions other than dishonorable from the period of service in which said injury or disease was incurred, or preexisting injury or disease was aggravated, compensation as provided in this subchapter, but no compensation shall be paid if the disability is a result of the veteran's own willful misconduct or abuse of alcohol or drugs."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1110?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1110. Basic entitlement","tname":"Veterans' Benefits","by":{"0":"11","1":"5"}},{"t":"usc","label":"38 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/38/1111","stext":{"head":"§1111. Presumption of sound condition","paras":[[0,"For the purposes of section 1110 of this title, every veteran shall be taken to have been in sound condition when examined, accepted, and enrolled for service, except as to defects, infirmities, or disorders noted at the time of the examination, acceptance, and enrollment, or where clear and unmistakable evidence demonstrates that the injury or disease existed before acceptance and enrollment and was not aggravated by such service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/1111?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§1111. Presumption of sound condition","tname":"Veterans' Benefits","by":{"0":"3, 11, 12, 13, 15, 20, 48, 50, 51","1":"passim","2":"4, 5, 15, 20, 21, 22, 23"}},{"t":"usc","label":"38 U.S.C. § 3004","url":"https://www.law.cornell.edu/uscode/text/38/3004","subs":["(a)(1958)"],"by":{"0":"7"}},{"t":"usc","label":"38 U.S.C. § 3010","url":"https://www.law.cornell.edu/uscode/text/38/3010","subs":["(g)(1962)"],"ar":1,"by":{"0":"8, 39"}},{"t":"usc","label":"38 U.S.C. § 3012","url":"https://www.law.cornell.edu/uscode/text/38/3012","subs":["(b)(6)(1962)"],"by":{"0":"8, 38"}},{"t":"usc","label":"38 U.S.C. § 4004","url":"https://www.law.cornell.edu/uscode/text/38/4004","subs":["(c)(1976)","(a)(1976)","(b)(1976)","(c)(1958)","(a)(1958)"],"ar":1,"tname":"Veterans' Benefits","by":{"0":"42","1":"23, 23, 23, 5","2":"10"}},{"t":"usc","label":"38 U.S.C. § 4061","url":"https://www.law.cornell.edu/uscode/text/38/4061","subs":["(a)(3)(1988)"],"by":{"0":"43"}},{"t":"usc","label":"38 U.S.C. § 4092","url":"https://www.law.cornell.edu/uscode/text/38/4092","subs":["(d)(1)(1988)"],"by":{"0":"43"}},{"t":"usc","label":"38 U.S.C. § 5100","url":"https://www.law.cornell.edu/uscode/text/38/5100","by":{"0":"4"}},{"t":"usc","label":"38 U.S.C. § 5104C","url":"https://www.law.cornell.edu/uscode/text/38/5104C","subs":["(a)(1)(C)","(b)","(a)"],"by":{"0":"5, 5","1":"6"}},{"t":"usc","label":"38 U.S.C. § 5107","url":"https://www.law.cornell.edu/uscode/text/38/5107","subs":["(b)"],"by":{"0":"4"}},{"t":"usc","label":"38 U.S.C. § 5108","url":"https://www.law.cornell.edu/uscode/text/38/5108","subs":["(a)","(2012)"],"stext":{"head":"§5108. Supplemental claims","paras":[[0,"(a) In General.—If new and relevant evidence is presented or secured with respect to a supplemental claim, the Secretary shall readjudicate the claim taking into consideration all of the evidence of record."],[0,"(b) Duty to Assist.—(1) If a claimant, in connection with a supplemental claim, reasonably identifies existing records, whether or not in the custody of a Federal department or agency, the Secretary shall assist the claimant in obtaining the records in accordance with section 5103A of this title."],[0,"(2) Assistance under paragraph (1) shall not be predicated upon a finding that new and relevant evidence has been presented or secured."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5108?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5108. Supplemental claims","tname":"Veterans' Benefits","by":{"0":"5","1":"6, 6","2":"19"}},{"t":"usc","label":"38 U.S.C. § 5109A","url":"https://www.law.cornell.edu/uscode/text/38/5109A","subs":["(a)","(b)","(c)","(d)"],"stext":{"head":"§5109A. Revision of decisions on grounds of clear and unmistakable error","paras":[[0,"(a) A decision by the Secretary under this chapter is subject to revision on the grounds of clear and unmistakable error. If evidence establishes the error, the prior decision shall be reversed or revised."],[0,"(b) For the purposes of authorizing benefits, a rating or other adjudicative decision that constitutes a reversal or revision of a prior decision on the grounds of clear and unmistakable error has the same effect as if the decision had been made on the date of the prior decision."],[0,"(c) Review to determine whether clear and unmistakable error exists in a case may be instituted by the Secretary on the Secretary's own motion or upon request of the claimant."],[0,"(d) A request for revision of a decision of the Secretary based on clear and unmistakable error may be made at any time after that decision is made."],[0,"(e) Such a request shall be submitted to the Secretary and shall be decided in the same manner as any other claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/5109A?type=usc&year=mostrecent&link-type=html"},"op":12,"head":"§5109A. Revision of decisions on grounds of clear and unmistakable error","tname":"Veterans' Benefits","by":{"0":"1, 3, 6, 9, 6, 16, 22, 45, 46, 6, 45, 22, 5, 6, 45","1":"6, 6","2":"3"}},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(a)(1)","(a)(3)","(a)(2012)","(a)"],"by":{"0":"6, 6","1":"6, 6, 6"}},{"t":"usc","label":"38 U.S.C. § 7103","url":"https://www.law.cornell.edu/uscode/text/38/7103","subs":["(c)"],"by":{"0":"5"}},{"t":"usc","label":"38 U.S.C. § 7104","url":"https://www.law.cornell.edu/uscode/text/38/7104","subs":["(c)","(a)","(b)"],"stext":{"head":"§7104. Jurisdiction of the Board; decisions; notice","paras":[[0,"(a) All questions in a matter which under section 511(a) of this title is subject to decision by the Secretary shall be subject to one review on appeal to the Secretary. Final decisions on such appeals shall be made by the Board. Decisions of the Board shall be based on the entire record in the proceeding and upon consideration of all evidence and material of record and applicable provisions of law and regulation."],[0,"(b) Except as provided in section 5108 of this title, when a claim is disallowed by the Board, the claim may not thereafter be readjudicated and allowed and a claim based upon the same factual basis may not be considered."],[0,"(c) The Board shall be bound in its decisions by the regulations of the Department, instructions of the Secretary, and the precedent opinions of the chief legal officer of the Department."],[0,"(d) Each decision of the Board shall include—"],[1,"(1) a written statement of the Board's findings and conclusions, and the reasons or bases for those findings and conclusions, on all material issues of fact and law presented on the record;"],[1,"(2) a general statement—"],[2,"(A) reflecting whether evidence was not considered in making the decision because the evidence was received at a time when not permitted under section 7113 of this title; and"],[2,"(B) noting such options as may be available for having the evidence considered by the Department; and"],[1,"(3) an order granting appropriate relief or denying relief."],[0,"(e) After reaching a decision on an appeal, the Board shall promptly issue notice (as that term is defined in section 5100 of this title) of such decision to the following:"],[1,"(1) The appellant."],[1,"(2) Any other party with a right to notice of such decision."],[1,"(3) Any authorized representative of the appellant or party described in paragraph (2)."],[0,"(f)(1) The Secretary may provide notice under subsection (e) electronically if a claimant (or the claimant's representative) elects to receive such notice electronically."],[0,"(2) A claimant (or the claimant's representative) may revoke such an election at any time, by means prescribed by the Secretary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7104?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§7104. Jurisdiction of the Board; decisions; notice","tname":"Veterans' Benefits","by":{"0":"42","1":"39, 39, 39","2":"10"}},{"t":"usc","label":"38 U.S.C. § 7105","url":"https://www.law.cornell.edu/uscode/text/38/7105","subs":["(b)(1)","(b)(1)(A)","(c)","(c)(1)"],"by":{"0":"5","1":"39, 39, 39, 39"}},{"t":"usc","label":"38 U.S.C. § 7111","url":"https://www.law.cornell.edu/uscode/text/38/7111","subs":["(a)","(b)","(c)","(d)"],"stext":{"head":"§7111. Revision of decisions on grounds of clear and unmistakable error","paras":[[0,"(a) A decision by the Board is subject to revision on the grounds of clear and unmistakable error. If evidence establishes the error, the prior decision shall be reversed or revised."],[0,"(b) For the purposes of authorizing benefits, a rating or other adjudicative decision of the Board that constitutes a reversal or revision of a prior decision of the Board on the grounds of clear and unmistakable error has the same effect as if the decision had been made on the date of the prior decision."],[0,"(c) Review to determine whether clear and unmistakable error exists in a case may be instituted by the Board on the Board's own motion or upon request of the claimant."],[0,"(d) A request for revision of a decision of the Board based on clear and unmistakable error may be made at any time after that decision is made."],[0,"(e) Such a request shall be submitted directly to the Board and shall be decided by the Board on the merits."],[0,"(f) A claim filed with the Secretary that requests reversal or revision of a previous Board decision due to clear and unmistakable error shall be considered to be a request to the Board under this section, and the Secretary shall promptly transmit any such request to the Board for its consideration under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7111?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":2,"head":"§7111. Revision of decisions on grounds of clear and unmistakable error","tname":"Veterans' Benefits","by":{"0":"1, 3, 9, 6, 16, 22, 45, 46, 49, 51, 6, 45, 22, 5, 6, 45","1":"39, 39, 39, 39","2":"3"}},{"t":"usc","label":"38 U.S.C. § 7252","url":"https://www.law.cornell.edu/uscode/text/38/7252","subs":["(a)"],"by":{"0":"5","1":"39, 39"}},{"t":"usc","label":"38 U.S.C. § 7261","url":"https://www.law.cornell.edu/uscode/text/38/7261","subs":["(a)(3)","(a)","(a)(3)(C)"],"stext":{"head":"§7261. Scope of review","paras":[[0,"(a) In any action brought under this chapter, the Court of Appeals for Veterans Claims, to the extent necessary to its decision and when presented, shall—"],[1,"(1) decide all relevant questions of law, interpret constitutional, statutory, and regulatory provisions, and determine the meaning or applicability of the terms of an action of the Secretary;"],[1,"(2) compel action of the Secretary unlawfully withheld or unreasonably delayed;"],[1,"(3) hold unlawful and set aside decisions, findings (other than those described in clause (4) of this subsection), conclusions, rules, and regulations issued or adopted by the Secretary, the Board of Veterans' Appeals, or the Chairman of the Board found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[2,"(D) without observance of procedure required by law; and"],[1,"(4) in the case of a finding of material fact adverse to the claimant made in reaching a decision in a case before the Department with respect to benefits under laws administered by the Secretary, hold unlawful and set aside or reverse such finding if the finding is clearly erroneous."],[0,"(b) In making the determinations under subsection (a), the Court shall review the record of proceedings before the Secretary and the Board of Veterans' Appeals pursuant to section 7252(b) of this title and shall—"],[1,"(1) take due account of the Secretary's application of section 5107(b) of this title; and"],[1,"(2) take due account of the rule of prejudicial error."],[0,"(c) In no event shall findings of fact made by the Secretary or the Board of Veterans' Appeals be subject to trial de novo by the Court."],[0,"(d) When a final decision of the Board of Veterans' Appeals is adverse to a party and the sole stated basis for such decision is the failure of the party to comply with any applicable regulation prescribed by the Secretary, the Court shall review only questions raised as to compliance with and the validity of the regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7261?type=usc&year=mostrecent&link-type=html"},"head":"§7261. Scope of review","tname":"Veterans' Benefits","by":{"0":"43","1":"39","2":"12"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(d)(1)","(a)","(c)","(d)"],"stext":{"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) After a decision of the United States Court of Appeals for Veterans Claims is entered in a case, any party to the case may obtain a review of the decision with respect to the validity of a decision of the Court on a rule of law or of any statute or regulation (other than a refusal to review the schedule of ratings for disabilities adopted under section 1155 of this title) or any interpretation thereof (other than a determination as to a factual matter) that was relied on by the Court in making the decision. Such a review shall be obtained by filing a notice of appeal with the Court of Appeals for Veterans Claims within the time and in the manner prescribed for appeal to United States courts of appeals from United States district courts."],[0,"(b)(1) When a judge or panel of the Court of Appeals for Veterans Claims, in making an order not otherwise appealable under this section, determines that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that there is in fact a disagreement between the appellant and the Secretary with respect to that question of law and that the ultimate termination of the case may be materially advanced by the immediate consideration of that question, the judge or panel shall notify the chief judge of that determination. Upon receiving such a notification, the chief judge shall certify that such a question is presented, and any party to the case may then petition the Court of Appeals for the Federal Circuit to decide the question. That court may permit an interlocutory appeal to be taken on that question if such a petition is filed with it within 10 days after the certification by the chief judge of the Court of Appeals for Veterans Claims. Neither the application for, nor the granting of, an appeal under this paragraph shall stay proceedings in the Court of Appeals for Veterans Claims, unless a stay is ordered by a judge of the Court of Appeals for Veterans Claims or by the Court of Appeals for the Federal Circuit."],[0,"(2) For purposes of subsections (d) and (e) of this section, an order described in this paragraph shall be treated as a decision of the Court of Appeals for Veterans Claims."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under this section, and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision. The judgment of such court shall be final subject to review by the Supreme Court upon certiorari, in the manner provided in section 1254 of title 28."],[0,"(d)(1) The Court of Appeals for the Federal Circuit shall decide all relevant questions of law, including interpreting constitutional and statutory provisions. The court shall hold unlawful and set aside any regulation or any interpretation thereof (other than a determination as to a factual matter) that was relied upon in the decision of the Court of Appeals for Veterans Claims that the Court of Appeals for the Federal Circuit finds to be—"],[1,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(B) contrary to constitutional right, power, privilege, or immunity;"],[1,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[1,"(D) without observance of procedure required by law."],[0,"(2) Except to the extent that an appeal under this chapter presents a constitutional issue, the Court of Appeals may not review (A) a challenge to a factual determination, or (B) a challenge to a law or regulation as applied to the facts of a particular case."],[0,"(e)(1) Upon such review, the Court of Appeals for the Federal Circuit shall have power to affirm or, if the decision of the Court of Appeals for Veterans Claims is not in accordance with law, to modify or reverse the decision of the Court of Appeals for Veterans Claims or to remand the matter, as appropriate."],[0,"(2) Rules for review of decisions of the Court of Appeals for Veterans Claims shall be those prescribed by the Supreme Court under section 2072 of title 28."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","tname":"Veterans' Benefits","by":{"0":"5, 43","1":"39, 10, 10, 10"}},{"t":"law","label":"Pub. L. No. 105-111","url":"https://www.govinfo.gov/link/plaw/105/public/111","by":{"0":"8"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"0":"43"}},{"t":"reg","label":"20 C.F.R. § 404.988","url":"https://www.ecfr.gov/current/title-20/section-404.988","subs":["(c)(8)"],"by":{"0":"28"}},{"t":"reg","label":"20 C.F.R. § 404.989","url":"https://www.ecfr.gov/current/title-20/section-404.989","subs":["(a)(3)","(b)"],"by":{"0":"28","1":"20, 42"}},{"t":"reg","label":"38 C.F.R. § 2.1009","url":"https://www.ecfr.gov/current/title-38/section-2.1009","subs":["(a)","(d)"],"by":{"0":"38, 7, 38"}},{"t":"reg","label":"38 C.F.R. § 3.9","url":"https://www.ecfr.gov/current/title-38/section-3.9","subs":["(a)","(d)"],"by":{"0":"38, 38"}},{"t":"reg","label":"38 C.F.R. § 3.105","url":"https://www.ecfr.gov/current/title-38/section-3.105","subs":["(a)","(d)"],"by":{"0":"38, 38, 8, 38, 3, 8, 9, 17, 33, 36, 37, 39, 36, 9, 34, 38","2":"13, 17, 18"}},{"t":"reg","label":"38 C.F.R. § 3.114","url":"https://www.ecfr.gov/current/title-38/section-3.114","subs":["(a)","(b)"],"by":{"0":"8, 36, 37, 39, 40, 8, 39, 8","2":"17, 18"}},{"t":"reg","label":"38 C.F.R. § 3.156","url":"https://www.ecfr.gov/current/title-38/section-3.156","by":{"0":"7"}},{"t":"reg","label":"38 C.F.R. § 3.304","url":"https://www.ecfr.gov/current/title-38/section-3.304","subs":["(b)"],"by":{"0":"12, 13","2":"5"}},{"t":"reg","label":"38 C.F.R. § 3.1531","url":"https://www.ecfr.gov/current/title-38/section-3.1531","subs":["(c)(8)"],"by":{"0":"7"}},{"t":"reg","label":"38 C.F.R. § 20.1403","url":"https://www.ecfr.gov/current/title-38/section-20.1403","by":{"0":"3, 9","2":"18"}},{"t":"reg","label":"38 C.F.R. § 20.1404","url":"https://www.ecfr.gov/current/title-38/section-20.1404","subs":["(b)"],"by":{"0":"47"}},{"t":"reg","label":"82 Fed. Reg. 12,270","url":"https://www.govinfo.gov/link/fr/82/12270","by":{"0":"29"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(5)"],"by":{"0":"48","2":"19, 13"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"ar":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"1":"24","2":"12, 13"}},{"t":"case","label":"American Tobacco Co. v. Patterson","cite":"456 U.S. 63","y":1982,"id":"1981/80-1199","sc":1,"sum":"The Court held that the absence of any sort of grandfather clause or explicit distinction between pre- and post-Act systems meant that the section applied to all seniority systems, regardless of when they were put in place. There was no clear legislative history to support the distinction between pre-existing systems and those that were implemented later.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Bell v. Derwinski","cite":"2 Vet. App. 611","y":1992,"url":"https://www.courtlistener.com/c/Vet.%20App./2/611/","op":1,"by":{"1":"38"}},{"t":"case","label":"Block v. Secretary of Veterans Affairs","cite":"641 F.3d 1313","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/641/1313/","by":{"1":"25"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Cook v. Principi","cite":"318 F.3d 1334","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/318/1334/","op":1,"by":{"1":"12, 36"}},{"t":"case","label":"Disabled Am. Veterans v. Gober","cite":"234 F.3d 682","y":2000,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/234/682/","op":3,"by":{"1":"29"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"1":"34, 39","2":"14"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"sum":"The Court found that the Individuals with Disabilities Education Act (IDEA) can authorize a public school to reimburse a student for private school tuition sought because the student never received special education services at the public school.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Halverson v. Slater","cite":"206 F.3d 1205","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/206/1205/","by":{"1":"27","2":"7"}},{"t":"case","label":"Kennedy v. Wilkie","cite":"33 Vet. App. 114","y":2020,"url":"https://www.courtlistener.com/c/Vet.%20App./33/114/","sum":"Holding that the term “VA issue approved by the Secretary or by the Secretary’s direction” in 38 C.F.R. 3.114(a) “is (1) a directive from or approved by the Secretary and (2) that is binding on VA”.","sumSrc":"brief:1","by":{"1":"30"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"1":"34"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Moffitt v. Brown","cite":"10 Vet. App. 214","y":1997,"url":"https://www.courtlistener.com/c/Vet.%20App./10/214/","by":{"1":"41"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"sum":"One of petitioner's predecessors as Secretary of Housing and Urban Development decided not to implement an \"operating subsidy\" program authorized by federal statute, which was intended to provide payments to owners of Government-subsidized apartment buildings to offset rising utility expenses and property taxes. Various plaintiffs, including respondent members of a nationwide class of Government-subsidized housing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27","2":"6, 7"}},{"t":"case","label":"Roberts v. Walters","cite":"792 F.2d 1109","y":1986,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/792/1109/","by":{"1":"25"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"op":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(d)"],"by":{"1":"27"}},{"t":"law","label":"Pub. L. No. 115-55","url":"https://www.govinfo.gov/link/plaw/115/public/55","by":{"1":"6"}},{"t":"usc","label":"38 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/38/211","subs":["(a)(1976)","(a)(1982)"],"by":{"1":"25, 25"}},{"t":"usc","label":"38 U.S.C. § 311","url":"https://www.law.cornell.edu/uscode/text/38/311","subs":["(1976)"],"by":{"1":"6, 9"}},{"t":"usc","label":"38 U.S.C. § 353","url":"https://www.law.cornell.edu/uscode/text/38/353","subs":["(1976)","(1977)"],"by":{"1":"6, 9","2":"22"}},{"t":"usc","label":"38 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/38/503","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"38 U.S.C. § 511","url":"https://www.law.cornell.edu/uscode/text/38/511","subs":["(a)","(b)(4)"],"stext":{"head":"§511. Decisions of the Secretary; finality","paras":[[0,"(a) The Secretary shall decide all questions of law and fact necessary to a decision by the Secretary under a law that affects the provision of benefits by the Secretary to veterans or the dependents or survivors of veterans. Subject to subsection (b), the decision of the Secretary as to any such question shall be final and conclusive and may not be reviewed by any other official or by any court, whether by an action in the nature of mandamus or otherwise."],[0,"(b) The second sentence of subsection (a) does not apply to—"],[1,"(1) matters subject to section 502 of this title;"],[1,"(2) matters covered by sections 1975 and 1984 of this title;"],[1,"(3) matters arising under chapter 37 of this title; and"],[1,"(4) matters covered by chapter 72 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/511?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§511. Decisions of the Secretary; finality","tname":"Veterans' Benefits","by":{"1":"5, 5"}},{"t":"usc","label":"38 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/38/1131","by":{"1":"5"}},{"t":"usc","label":"38 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/38/1151","by":{"1":"38"}},{"t":"usc","label":"38 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/38/1153","by":{"1":"6, 9","2":"22"}},{"t":"usc","label":"38 U.S.C. § 4001","url":"https://www.law.cornell.edu/uscode/text/38/4001","subs":["(a)(1958)","(a)(1976)"],"by":{"1":"23, 6"}},{"t":"usc","label":"38 U.S.C. § 4005","url":"https://www.law.cornell.edu/uscode/text/38/4005","subs":["(b)(1)(1976)","(c)(1976)"],"by":{"1":"5, 5"}},{"t":"usc","label":"38 U.S.C. § 5101","url":"https://www.law.cornell.edu/uscode/text/38/5101","subs":["(a)(1)(A)"],"by":{"1":"5"}},{"t":"usc","label":"38 U.S.C. § 5104","url":"https://www.law.cornell.edu/uscode/text/38/5104","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"38 U.S.C. § 5104B","url":"https://www.law.cornell.edu/uscode/text/38/5104B","subs":["(a)","(e)"],"by":{"1":"6, 6"}},{"t":"usc","label":"38 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/38/7101","subs":["(a)"],"by":{"1":"6"}},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)"],"by":{"1":"39"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"32","2":"16"}},{"t":"reg","label":"70 Fed. Reg. 23,027","url":"https://www.govinfo.gov/link/fr/70/23027","by":{"1":"10"}},{"t":"case","label":"Chapman v. Houston Welfare Rts. Org.","cite":"441 U.S. 600","y":1979,"id":"1978/77-719","sc":1,"sum":"Federal district courts' jurisdiction under §§ 1343 (3) and (4) does not encompass claims, such as those involved here, that a state welfare regulation is invalid because it conflicts with the Social Security Act, and hence the District Court in neither case had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Guardians Ass’n v. Civ. Serv. Comm’n of New York","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Horn v. Shinseki","cite":"25 Vet. App. 231","y":2012,"url":"https://www.courtlistener.com/c/Vet.%20App./25/231/","by":{"2":"21"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"Miller v. West","cite":"11 Vet. App. 345","y":1998,"url":"https://www.courtlistener.com/c/Vet.%20App./11/345/","by":{"2":"21"}},{"t":"case","label":"Patrick v. Shinseki","cite":"668 F.3d 1325","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/668/1325/","by":{"2":"6"}},{"t":"case","label":"Pauley v. BethEnergy Mines, Inc.","cite":"501 U.S. 680","y":1991,"id":"1990/89-1714","sc":1,"sum":"The third and fourth rebuttal provisions in the DOL regulations do not render those regulations \"more restrictive than\" the HEW regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Presley v. Etowah Cnty. Comm’n","cite":"502 U.S. 491","y":1992,"id":"1991/90-711","sc":1,"sum":"In a majority opinion authored by Justice Anthony M. Kennedy, the Court determined that section 5 of the Voting Rights Act covers only changes that directly relate to voting.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"United States v. Grimaud","cite":"220 U.S. 506","y":1911,"id":"scdb/1910-122","sc":1,"sum":"Under the acts establishing forest reservations, their use for grazing or other lawful purposes is subject to rules and regulations established by the Secretary of Agriculture, and it being impracticable for Congress to provide general regulations, that body acted within its constitutional power in conferring power on the Secretary to establish such rules; the power so conferred being administrative and not …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Util. Air Regul. Grp. v. E.P.A.","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"reg","label":"38 C.F.R. § 3.306","url":"https://www.ecfr.gov/current/title-38/section-3.306","subs":["(a)","(b)"],"by":{"2":"22, 22"}}]};